function generateLineupsData(n,t){t.preventDefault();var i=$("#generateLineupsData").serialize();console.log(i);$.ajax({type:"POST",url:urlPrefix()+"/Match/Lineups?matchId="+n+"&"+i,contentType:"application/json; charset=utf-8",success:function(t){$("#btnApplyLineups").on("click",function(){console.log("ASdasdads");applyLineups(n,t)});$("#lineupsRequestContent").text("");jsonView.format(t,"#lineupsRequestContent");$("#lineupsRequest").modal()},error:function(){console.log("failed")}})}function applyLineups(n,t){$.ajax({type:"POST",url:urlPrefix()+"/Match/Lineups/"+n,contentType:"application/json; charset=utf-8",dataType:"json",data:JSON.stringify(t),success:function(){console.log("success")},error:function(){console.log("failed")}})}function getRootUrl(){return window.location.origin?window.location.origin+"/":window.location.protocol+"/"+window.location.host+"/"}function urlPrefix(){return getRootUrl()+$("#urlPrefix").val()}